import edu.rice.cs.plt.lambda.Thunk;
import edu.rice.cs.plt.tuple.Option;

public class DeclaredVariable extends Variable {

    protected final LValue _lvalue;
    protected int _position;
    protected boolean _isEntireLHS; // necessary when assigning a tuple expr to a singleton

    public DeclaredVariable(LValue lvalue, VarDecl decl) {
        _lvalue = lvalue;

        // Figure out my position in the decl.
        int i = 0;
        for (LValue lv : decl.getLhs()) {
            // lvalue came from decl in the first place, so referential equality
            // works just fine.
            if (lv == lvalue) {
                _position = i;
                break;
            }
            ++i;
        }

        _isEntireLHS = (decl.getLhs().size() == 1);

        Option<TypeOrPattern> tp = _lvalue.getIdType();
        if (tp.isSome() && tp.unwrap() instanceof Type)
            _thunk = Option.<Thunk<Option<Type>>>some(SimpleBox.make(NodeUtil.optTypeOrPatternToType(tp)));
    }

    public LValue ast() {
        return _lvalue;
    }

    public Modifiers modifiers() {
        return _lvalue.getMods();
    }

    public boolean mutable() {
        return _lvalue.isMutable();
    }

    public boolean isEntireLHS() {
        return _isEntireLHS;
    }

    public int position() {
        return _position;
    }

    @Override
    public boolean hasExplicitType() {
        return _lvalue.getIdType().isSome();
    }

    @Override
    public String toString() {
        return _lvalue.toString();
    }

    @Override
    public Span getSpan() {
        return NodeUtil.getSpan(_lvalue);
    }
}

public void forComponent(Component x) {
    debug("forComponent ",x.getName(),NodeUtil.getSpan(x));

    for ( Import i : x.getImports() ) {
        i.accept(this);
    }

    // determineOverloadedNames(x.getDecls() );

    // Must do this first, to get local decls right.
    topLevelOverloadedNamesAndSigs = generateTopLevelOverloads(thisApi(), topLevelOverloads, typeAnalyzer, cw, this, OverloadSet.localFactory);

    /* Need wrappers for the API, too. */

    // Must process top-level values next to make sure fields end up in scope.
    // Every top-level variable's binding is registered before any code is
    // generated, because an initializer may refer to a variable declared
    // later in the component; without this, generating that initializer
    // reaches forVarRef's fresh-import path, which assumes the shape of an
    // immutable variable's field.
    for (Decl d : x.getDecls()) {
